package com.digipals.wms.finance.entity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="accrual_runs",uniqueConstraints=@UniqueConstraint(columnNames={"template_id","period_start"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class AccrualRun { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="template_id",nullable=false) AccrualTemplate template; LocalDate periodStart; BigDecimal amount; UUID accountingDocumentId; }